package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.junit.jupiter.api.Test;
import static com.consense.service.drafting.DraftReviewGraph.*;
import static org.junit.jupiter.api.Assertions.*;

/** Current native proof fixtures only; no product database, parser or real model calls. */
class DraftReferenceSupplementCompatibilityTest {
    static final String SHA=String.join("",Collections.nCopies(64,"b"));

    @Test void currentNativeContextCanGrowWhileSavedExternalProofAndFrozenGroupsRemainUnchanged(){
        ObjectNode reading=source(false);Map<String,Object> base=base(reading);String humanBefore=JsonUtils.write(nodes(base).get(0));DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base);Map<String,Object> saved=manifest(plan);String before=JsonUtils.write(saved);
        assertTrue(DraftAutomationService.referenceSupplementCompatible(JsonUtils.mapper().valueToTree(saved),plan,1));assertFalse(DraftAutomationService.savedPlanCompatible(before,JsonUtils.write(obj("execution","fixed-root-groups-v1","concurrency",1,"groups",DraftAutomaticDiscovery.planGroups(plan),"plan",plan.descriptor()))),"The old exact guard must still reject changed proof/group identity");
        List<Map<String,Object>> frozen=maps(saved.get("groups"));assertNotEquals(frozen.size(),DraftAutomaticDiscovery.planGroups(plan).size(),"Fresh routing would change the buckets");assertEquals(JsonUtils.write(frozen),JsonUtils.write(DraftAutomaticDiscovery.frozenGroups(plan,frozen)));assertEquals(before,JsonUtils.write(saved));assertEquals(humanBefore,JsonUtils.write(nodes(base).get(0)));
        String bq=task(plan,"bq");Map<String,Object> packet=map(DraftAutomaticDiscovery.knownRootPacket(plan,Collections.singleton(bq)).get(0));assertEquals("electronicTendering",packet.get("id"));assertEquals(false,packet.get("rulePatchAllowed"));assertEquals(Collections.singletonList(bq),packet.get("sourceTaskIds"));Map<String,Object> descriptor=root(plan,"electronicTendering");assertEquals("23",map(list(descriptor.get("sourceReferences")).get(0)).get("sourceId"),"The human NTT proof is retained rather than replaced by SCT context");
    }

    @Test void sourceTaskCoverageRestorationRootIdentityCoreAndExecutionChangesAreRejected(){
        ObjectNode reading=source(false);DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base(reading));String original=JsonUtils.write(manifest(plan));
        for(String field:Arrays.asList("sourceIds","tasks","coverage","restoredDefinitionIds")){ObjectNode changed=(ObjectNode)JsonUtils.parse(original);((ObjectNode)changed.path("plan")).put(field,"changed");assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1),field);}
        for(String field:Arrays.asList("id","wireId","baselineKey","definitionSha256")){ObjectNode changed=(ObjectNode)JsonUtils.parse(original);((ObjectNode)changed.path("plan").path("knownRoots").path(0)).put(field,"changed");assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1),field);}
        ObjectNode changed=(ObjectNode)JsonUtils.parse(original);changed.put("concurrency",2);assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1));changed=(ObjectNode)JsonUtils.parse(original);((ObjectNode)changed.path("plan")).putArray("knownRoots");assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1));
        Map<String,Object> alteredBase=base(reading);nodes(alteredBase).get(0).put("manual",false);DraftAutomaticDiscovery.Plan altered=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),alteredBase);assertFalse(DraftAutomationService.referenceSupplementCompatible(JsonUtils.parse(original),altered,1),"A real core/status/manual change is not context supplementation");
    }

    @Test void legacyGroupedPlanMissingSourceIdsUsesOnlyTheExistingExactSourceSetUpgrade(){
        ObjectNode reading=source(false);DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base(reading));String original=JsonUtils.write(manifest(plan));ObjectNode legacy=(ObjectNode)JsonUtils.parse(original);((ObjectNode)legacy.path("plan")).remove("sourceIds");String before=legacy.toString();assertTrue(DraftAutomationService.referenceSupplementCompatible(legacy,plan,1));assertEquals(before,legacy.toString(),"Legacy normalization must touch only a JSON copy, not the saved manifest");
        ObjectNode changed=(ObjectNode)JsonUtils.parse(before);((ObjectNode)changed.path("plan").path("coverage").path("sources").path(0)).put("sourceId","25");assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1),"A different legacy source set cannot be upgraded");changed=(ObjectNode)JsonUtils.parse(before);((ObjectNode)changed.path("plan").path("coverage")).remove("sources");assertFalse(DraftAutomationService.referenceSupplementCompatible(changed,plan,1),"Missing source coverage is not a legacy identity proof");
        ObjectNode explicit=(ObjectNode)JsonUtils.parse(original);explicit.set("sourceSelection",JsonUtils.mapper().valueToTree(obj("version",1,"sourceIds",Collections.singletonList("24"),"protectedSourceIds",Arrays.asList("23","24"))));assertTrue(DraftAutomationService.referenceSupplementCompatible(explicit,plan,1));((ObjectNode)explicit.path("plan")).remove("sourceIds");assertFalse(DraftAutomationService.referenceSupplementCompatible(explicit,plan,1),"An explicit source selection cannot borrow the no-selection legacy exception");explicit=(ObjectNode)JsonUtils.parse(original);explicit.set("sourceSelection",JsonUtils.mapper().valueToTree(obj("version",1,"sourceIds",Collections.singletonList("25"),"protectedSourceIds",Arrays.asList("23","24","25"))));assertFalse(DraftAutomationService.referenceSupplementCompatible(explicit,plan,1),"A sourceSelection mismatch is rejected even if plan.sourceIds still matches");
    }

    @Test void oldProofOwnerAndPrerequisiteRecordsCannotBeRemovedAlteredOrDuplicated(){
        ObjectNode reading=source(false);DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base(reading));Map<String,Object> original=manifest(plan);
        for(String field:Arrays.asList("sourceReferences","taskIds","prerequisiteForTaskIds")){Map<String,Object> changed=JsonUtils.readMap(JsonUtils.write(original));Map<String,Object> root=map(list(map(changed.get("plan")).get("knownRoots")).get(0));List<Object> values=new ArrayList<>(list(root.get(field)));values.add("sourceReferences".equals(field)?obj("taskId","old-proof","sourceId","24","sourceSha256",SHA,"sourceObservationId","previous-observation"):"old-task");root.put(field,values);assertFalse(DraftAutomationService.referenceSupplementCompatible(JsonUtils.mapper().valueToTree(changed),plan,1),field);}
        Map<String,Object> duplicate=JsonUtils.readMap(JsonUtils.write(original));Map<String,Object> root=map(list(map(duplicate.get("plan")).get("knownRoots")).get(0));List<Object> refs=new ArrayList<>(list(root.get("sourceReferences")));refs.add(refs.get(0));root.put("sourceReferences",refs);assertFalse(DraftAutomationService.referenceSupplementCompatible(JsonUtils.mapper().valueToTree(duplicate),plan,1));
        Map<String,Object> reverse=JsonUtils.readMap(JsonUtils.write(original));root=map(list(map(reverse.get("plan")).get("knownRoots")).get(0));root.put("existing",true);assertFalse(DraftAutomationService.referenceSupplementCompatible(JsonUtils.mapper().valueToTree(reverse),plan,1),"Existing true must not become false");
    }

    @Test void selectedSourceAndRealTaskAreInsufficientWithoutTheRootsOwnNativeProof(){
        ObjectNode reading=source(true);Map<String,Object> clean=base(reading);DraftAutomaticDiscovery.Plan trusted=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),clean);JsonNode saved=JsonUtils.mapper().valueToTree(manifest(trusted));String unrelated=task(trusted,"unrelated"),rootId=text(root(trusted,"electronicTendering").get("id"));assertFalse(trusted.currentOwnerProof(rootId,unrelated));assertFalse(trusted.currentPrerequisiteProof(rootId,unrelated,null));
        for(String defect:Arrays.asList("unrelated-owner","foreign-source","wrong-sha","wrong-observation","invented-prerequisite")){
            Map<String,Object> forged=JsonUtils.readMap(JsonUtils.write(clean)),reference=map(nodes(forged).get(0).get("currentDefinitionReference"));Map<String,Object> task=trusted.tasks().stream().filter(row->unrelated.equals(row.get("taskId"))).findFirst().orElseThrow(AssertionError::new);Map<String,Object> proof=obj("taskId",unrelated,"sourceId","24","sourceSha256",SHA,"sourceObservationId",task.get("sourceObservationId"));if("foreign-source".equals(defect))proof.put("sourceId","25");if("wrong-sha".equals(defect))proof.put("sourceSha256",String.join("",Collections.nCopies(64,"a")));if("wrong-observation".equals(defect))proof.put("sourceObservationId","bq");if("invented-prerequisite".equals(defect))proof.put("prerequisiteOfBaselineKey","domesticBlocks");List<Object> refs=new ArrayList<>(list(reference.get("sourceReferences")));refs.add(proof);reference.put("sourceReferences",refs);List<Object> owners=new ArrayList<>(list(reference.get("taskIds")));owners.add(unrelated);reference.put("taskIds",owners);DraftAutomaticDiscovery.Plan candidate=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),forged);
            assertEquals(root(trusted,"electronicTendering").get("definitionSha256"),root(candidate,"electronicTendering").get("definitionSha256"),"A forged source claim does not need a core change to be rejected");assertFalse(DraftAutomationService.referenceSupplementCompatible(saved,candidate,1),defect);
        }
        for(String defect:Arrays.asList("missing-current-source-proof","dangling-old-owner","dangling-old-prerequisite")){
            Map<String,Object> forged=JsonUtils.readMap(JsonUtils.write(clean)),reference=map(nodes(forged).get(0).get("currentDefinitionReference"));if("missing-current-source-proof".equals(defect)){reference.put("sourceReferences",Collections.singletonList(obj("taskId","missing-current-task","sourceId","24","sourceSha256",SHA,"sourceObservationId","missing-current-observation")));reference.put("taskIds",Collections.singletonList("missing-current-task"));}else reference.put("dangling-old-owner".equals(defect)?"taskIds":"prerequisiteForTaskIds",Collections.singletonList("unproven-external-task"));DraftAutomaticDiscovery.Plan candidate=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),forged);assertFalse(DraftAutomationService.referenceSupplementCompatible(JsonUtils.mapper().valueToTree(manifest(candidate)),candidate,1),"Even unchanged historical metadata must not grandfather a missing current-source task or an owner without a real external proof: "+defect);
        }
    }

    @Test void frozenGroupsRejectMissingDuplicateForeignAndMovedSourceIdentitiesBeforeInstallation(){
        ObjectNode reading=source(false);DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base(reading));List<Map<String,Object>> original=frozen(plan);String planned=JsonUtils.write(DraftAutomaticDiscovery.planGroups(plan));
        for(String defect:Arrays.asList("missing","duplicate-task","group-id","source","source-sha")){List<Map<String,Object>> changed=maps(JsonUtils.readMap(JsonUtils.write(obj("groups",original))).get("groups"));if("missing".equals(defect))changed.remove(0);if("duplicate-task".equals(defect))changed.add(JsonUtils.readMap(JsonUtils.write(changed.get(0))));if("group-id".equals(defect))changed.get(0).put("taskId","group-changed");if("source".equals(defect))changed.get(0).put("sourceIds",Collections.singletonList("25"));if("source-sha".equals(defect))map(list(changed.get(0).get("sources")).get(0)).put("sourceSha256","changed");assertThrows(RuntimeException.class,()->DraftAutomaticDiscovery.frozenGroups(plan,changed),defect);assertEquals(planned,JsonUtils.write(DraftAutomaticDiscovery.planGroups(plan)),"Rejected groups cannot partially install a new partition");}
    }

    static ObjectNode source(boolean extra){ObjectNode reading=JsonUtils.mapper().createObjectNode().put("id","24").put("sourceDocumentId",24).put("fileKey","SCT").put("format","docx").put("sourceSha256",SHA).put("analysisRevision","supplement-native").put("analysisInputSha256",SHA).put("analysisSha256",SHA).put("evidenceStatus","bound");for(String field:Arrays.asList("sourceMembers","paragraphs","guidanceNotes","markerCandidates","groups","conditions"))reading.putArray(field);add(reading,"domestic-new",DraftBusinessRules.standardParagraph("SCT",547),"Current SCT4 domestic clause.");add(reading,"domestic-old",DraftBusinessRules.standardParagraph("SCT",859),"Current SCT6 domestic proposal clause.");add(reading,"bq",DraftBusinessRules.standardParagraph("SCT",55),"Bills of Quantities issued in L10Pro and issued in hard copy.");if(extra)add(reading,"unrelated","Confirm the site inspection arrangements.","An independent current source clause.");return reading;}
    static Map<String,Object> base(ObjectNode reading){Map<String,Object> graph=obj("kind","consense-template-graph-v1","sources",Arrays.asList(obj("id","23","fileKey","NTT","format","docx","sourceSha256",SHA),obj("id","24","fileKey","SCT","format","docx","sourceSha256",SHA)),"selectedDocuments",obj("NTT","23","SCT","24"),"graph",obj("variables",new ArrayList<>(),"events",new ArrayList<>()));DraftAutomaticDiscovery.Plan initial=DraftAutomaticDiscovery.plan(Collections.singletonList(reading));Map<String,Object> bq=DraftAutomaticDiscovery.receiptNodes(initial,Collections.emptyList()).stream().filter(node->"electronicTendering".equals(map(node.get("catalogAlignment")).get("baselineKey"))).findFirst().orElseThrow(AssertionError::new);bq.put("status","confirmed");bq.put("manual",true);map(bq.get("catalogAlignment")).put("status","matched");map(bq.get("catalogAlignment")).put("confirmed",true);map(bq.get("catalogAlignment")).put("reason","The fixture reviewer compared the complete issue-format definition and its L10Pro/Hardcopy domain; this is the same business fact, with no project answer adopted.");bq.put("definitionReview",obj("confirmed",true));bq.put("docIds",Arrays.asList("23","24"));Map<String,Object> reference=map(bq.get("currentDefinitionReference"));reference.put("sourceReferences",Collections.singletonList(obj("taskId","historic-ntt-task","sourceId","23","sourceSha256",SHA,"sourceObservationId","historic-ntt-guidance")));reference.put("taskIds",Collections.singletonList("historic-ntt-task"));reference.put("taskQuotes",obj("historic-ntt-task","A previously reviewed NTT issue-format instruction."));state(graph).put("variables",new ArrayList<>(Collections.singletonList(bq)));return graph;}
    static Map<String,Object> manifest(DraftAutomaticDiscovery.Plan plan){Map<String,Object> descriptor=JsonUtils.readMap(JsonUtils.write(plan.descriptor()));String added=task(plan,"domestic-new");for(Object raw:list(descriptor.get("knownRoots"))){Map<String,Object> root=map(raw);if(!"domesticBlocks".equals(root.get("baselineKey")))continue;List<Object> refs=new ArrayList<>(list(root.get("sourceReferences")));refs.removeIf(row->added.equals(map(row).get("taskId")));root.put("sourceReferences",refs);List<Object> owners=new ArrayList<>(list(root.get("taskIds")));owners.remove(added);root.put("taskIds",owners);}return obj("execution","fixed-root-groups-v1","plan",descriptor,"groups",frozen(plan),"concurrency",1);}
    static List<Map<String,Object>> frozen(DraftAutomaticDiscovery.Plan plan){List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> task:plan.tasks()){Map<String,Object> template=DraftAutomaticDiscovery.planGroups(plan).stream().filter(group->list(group.get("taskIds")).contains(task.get("taskId"))).findFirst().orElseThrow(AssertionError::new);Map<String,Object> group=JsonUtils.readMap(JsonUtils.write(template));List<Object> ids=Collections.singletonList(task.get("taskId"));group.put("taskId","group-"+DraftAdoption.hash(JsonUtils.write(ids)).substring(0,24));group.put("taskIds",ids);group.put("memberCount",new HashSet<>(list(task.get("memberIds"))).size());result.add(group);}return result;}
    static String task(DraftAutomaticDiscovery.Plan plan,String observation){return text(plan.tasks().stream().filter(task->observation.equals(task.get("sourceObservationId"))).findFirst().orElseThrow(AssertionError::new).get("taskId"));}
    static Map<String,Object> root(DraftAutomaticDiscovery.Plan plan,String key){return list(plan.descriptor().get("knownRoots")).stream().map(DraftReviewGraph::map).filter(root->key.equals(root.get("baselineKey"))).findFirst().orElseThrow(AssertionError::new);}
    static List<Map<String,Object>> maps(Object rows){List<Map<String,Object>> result=new ArrayList<>();for(Object row:list(rows))result.add(map(row));return result;}
    private static void add(ObjectNode reading,String id,String quote,String body){assertFalse(quote.isEmpty());member(reading,id+"-note",quote);member(reading,id+"-body",body);ObjectNode note=reading.withArray("guidanceNotes").addObject().put("id",id).put("text",quote).put("captureComplete",true);note.putArray("memberRanges").addObject().put("memberId",id+"-note").put("channel","text").put("start",0).put("end",quote.length());ObjectNode scope=reading.withArray("groups").addObject().put("id",id+"-scope").put("text",body).put("scopeComplete",true);scope.putArray("guidanceNoteIds").add(id);scope.putArray("memberRanges").addObject().put("memberId",id+"-body").put("channel","text").put("start",0).put("end",body.length());}
    private static void member(ObjectNode reading,String id,String value){ObjectNode member=reading.withArray("sourceMembers").addObject().put("id",id).put("identityStatus","source_bound");member.putObject("textObservation").put("text",value);member.putObject("sourcePosition").put("sourceSha256",SHA).put("partName","word/document.xml").put("nodePath","/supplement/"+id);ObjectNode paragraph=reading.withArray("paragraphs").addObject().put("id","p-"+id).put("text",value).put("sourceSha256",SHA).put("paragraphSha256",DraftAdoption.hash(value));paragraph.set("sourcePosition",member.path("sourcePosition").deepCopy());}
}
